/**
 * Login-page backdrop artwork: Sayram Lake photo (provided by the user,
 * 2026-09-13), resized to 2560×1190 and JPEG-compressed (q58). Inlined as a
 * data URI so Vite and Next.js resolve it identically without asset-pipeline
 * coupling — same pattern as lynse-logo.ts.
 *
 * The image rights belong to the photographer; swap in different artwork by
 * encoding it with `base64 -i <file> | tr -d '\n'` and pasting it below,
 * keeping the data URI prefix in sync with the actual format.
 */
export const LOGIN_BG_SRC =
  "data:image/jpeg;base64,";
